{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "count_semantics",
      "alternatives": [
        "df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES'] == df['IN_PKTS'] + df['OUT_PKTS']",
        "df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES'] <= df['IN_PKTS'] + df['OUT_PKTS']"
      ],
      "features": [
        "NUM_PKTS_UP_TO_128_BYTES",
        "NUM_PKTS_128_TO_256_BYTES",
        "NUM_PKTS_256_TO_512_BYTES",
        "NUM_PKTS_512_TO_1024_BYTES",
        "NUM_PKTS_1024_TO_1514_BYTES",
        "IN_PKTS",
        "OUT_PKTS"
      ],
      "rationale": "The packet size distribution counts should sum to the total number of packets in the flow, but packets larger than 1514 bytes may not be counted."
    },
    {
      "id": "R2",
      "category": "count_semantics",
      "alternatives": [
        "df['RETRANSMITTED_IN_PKTS'] <= df['IN_PKTS']"
      ],
      "features": [
        "RETRANSMITTED_IN_PKTS",
        "IN_PKTS"
      ],
      "rationale": "Retransmitted packets in the source-to-destination direction are a subset of all packets in that direction."
    },
    {
      "id": "R3",
      "category": "count_semantics",
      "alternatives": [
        "df['RETRANSMITTED_OUT_PKTS'] <= df['OUT_PKTS']"
      ],
      "features": [
        "RETRANSMITTED_OUT_PKTS",
        "OUT_PKTS"
      ],
      "rationale": "Retransmitted packets in the destination-to-source direction are a subset of all packets in that direction."
    }
  ]
}
